inline bool Foam::word::valid(char c)
{
    return
    (
        !isspace(c)
     && c != '"'
     && c != '\''
     && c != '/'
     && c != '$'
     && c != ';'
     && c != '{'
     && c != '}'
    );
}


inline Foam::word Foam::word::capitalise() const
{
    word w(*this);
    w[0] = toupper(w[0]);
    return w;
}




