template<class T>
Foam::Ostream& Foam::operator<<
(
    Foam::Ostream& os,
    const Foam::UIndirectList<T>& L
)
{

    if (os.format() == IOstream::ASCII || !contiguous<T>())
    {
        bool uniform = false;

        if (L.size() > 1 && contiguous<T>())
        {
            uniform = true;

            for (Foam::label i=0; i<(L).size(); i++)
            {
                if (L[i] != L[0])
                {
                    uniform = false;
                    break;
                }
            }
        }

        if (uniform)
        {

            os << L.size() << token::BEGIN_BLOCK;


            os << L[0];


            os << token::END_BLOCK;
        }
        else if (L.size() <= 1 || (L.size() < 11 && contiguous<T>()))
        {

            os << L.size() << token::BEGIN_LIST;


            for (Foam::label i=0; i<(L).size(); i++)
            {
                if (i) os << token::SPACE;
                os << L[i];
            }


            os << token::END_LIST;
        }
        else
        {

            os << nl << L.size() << nl << token::BEGIN_LIST;


            for (Foam::label i=0; i<(L).size(); i++)
            {
                os << nl << L[i];
            }


            os << nl << token::END_LIST << nl;
        }
    }
    else
    {


        os << nl << L.size() << nl;

        if (L.size())
        {
            List<T> lst = L();

            os.write
            (
                reinterpret_cast<const char*>(lst.cdata()),
                lst.byteSize()
            );
        }
    }


    os.check("Ostream& operator<<(Ostream&, const UIndirectList&)");

    return os;
}
