template<class Type>
Foam::Ostream& Foam::operator<<(Ostream& os, const dimensioned<Type>& dt)
{

    os << dt.name() << token::SPACE;


    scalar mult;
    dt.dimensions().write(os, mult);

    os << token::SPACE;


    os << dt.value()/mult;


    os.check("Ostream& operator<<(Ostream&, const dimensioned<Type>&)");

    return os;
}




