inline SymmTensor<Cmpt>
operator+(const DiagTensor<Cmpt>& dt1, const SymmTensor<Cmpt>& t2)
{
    return SymmTensor<Cmpt>
    (
        dt1.xx() + t2.xx(), t2.xy(), t2.xz(),
                            dt1.yy() + t2.yy(), t2.yz(),
                                                dt1.zz() + t2.zz()
    );
}


template<class Cmpt>
inline SymmTensor<Cmpt>
operator+(const SymmTensor<Cmpt>& t1, const DiagTensor<Cmpt>& dt2)
{
    return SymmTensor<Cmpt>
    (
        t1.xx() + dt2.xx(), t1.xy(), t1.xz(),
                            t1.yy() + dt2.yy(), t1.yz(),
                                                t1.zz() + dt2.zz()
    );
}


template<class Cmpt>
inline SymmTensor<Cmpt>
operator-(const DiagTensor<Cmpt>& dt1, const SymmTensor<Cmpt>& t2)
{
    return SymmTensor<Cmpt>
    (
        dt1.xx() - t2.xx(), -t2.xy(), -t2.xz(),
                             dt1.yy() - t2.yy(), -t2.yz(),
                                                  dt1.zz() - t2.zz()
    );
}


template<class Cmpt>
inline SymmTensor<Cmpt>
operator-(const SymmTensor<Cmpt>& t1, const DiagTensor<Cmpt>& dt2)
{
    return SymmTensor<Cmpt>
    (
        t1.xx() - dt2.xx(), t1.xy(), t1.xz(),
                            t1.yy() - dt2.yy(), t1.yz(),
                                                t1.zz() - dt2.zz()
    );
}



template<class Cmpt>
inline DiagTensor<Cmpt>
operator&(const DiagTensor<Cmpt>& dt1, const DiagTensor<Cmpt>& dt2)
{
    return DiagTensor<Cmpt>
    (
        dt1.xx()*dt2.xx(),
        dt1.yy()*dt2.yy(),
        dt1.zz()*dt2.zz()
    );
}



template<class Cmpt>
inline Tensor<Cmpt>
operator&(const DiagTensor<Cmpt>& dt1, const Tensor<Cmpt>& t2)
{
    return Tensor<Cmpt>
    (
        dt1.xx()*t2.xx(),
        dt1.xx()*t2.xy(),
        dt1.xx()*t2.xz(),

                          dt1.yy()*t2.yx(),
                          dt1.yy()*t2.yy(),
                          dt1.yy()*t2.yz(),

                                            dt1.zz()*t2.zx(),
                                            dt1.zz()*t2.zy(),
                                            dt1.zz()*t2.zz()
    );
}



template<class Cmpt>
inline Tensor<Cmpt>
operator&(const Tensor<Cmpt>& t1, const DiagTensor<Cmpt>& dt2)
{
    return Tensor<Cmpt>
    (
        t1.xx()*dt2.xx(),
                          t1.xy()*dt2.yy(),
                                            t1.xz()*dt2.zz(),

        t1.yx()*dt2.xx(),
                          t1.yy()*dt2.yy(),
                                            t1.yz()*dt2.zz(),

        t1.zx()*dt2.xx(),
                          t1.zy()*dt2.yy(),
                                            t1.zz()*dt2.zz()
    );
}



template<class Cmpt>
inline Vector<Cmpt>
operator&(const DiagTensor<Cmpt>& dt, const Vector<Cmpt>& v)
{
    return Vector<Cmpt>
    (
        dt.xx()*v.x(),
                       dt.yy()*v.y(),
                                      dt.zz()*v.z()
    );
}



template<class Cmpt>
inline Vector<Cmpt>
operator&(const Vector<Cmpt>& v, const DiagTensor<Cmpt>& dt)
{
    return Vector<Cmpt>
    (
        v.x()*dt.xx(),
                       v.y()*dt.yy(),
                                      v.z()*dt.zz()
    );
}



template<class Cmpt>
inline DiagTensor<Cmpt>
operator/(const scalar s, const DiagTensor<Cmpt>& dt)
{
    return DiagTensor<Cmpt>(s/dt.xx(), s/dt.yy(), s/dt.zz());
}



