template<class PointField>
Foam::point Foam::face::centre(const PointField& ps)
{

    if (ps.size() == 3)
    {
        return (1.0/3.0)*(ps[0] + ps[1] + ps[2]);
    }




    point pAvg = Zero;
    for (Foam::label pi=0; pi<(ps).size(); pi++)
    {
        pAvg += ps[pi];
    }
    pAvg /= ps.size();




    vector sumA = Zero;
    for (Foam::label pi=0; pi<(ps).size(); pi++)
    {
        const point& p = ps[pi];
        const point& pNext = ps[ps.fcIndex(pi)];

        const vector a = (pNext - p)^(pAvg - p);

        sumA += a;
    }
    const vector sumAHat = normalised(sumA);





    scalar sumAn = 0;
    vector sumAnc = Zero;
    for (Foam::label pi=0; pi<(ps).size(); pi++)
    {
        const point& p = ps[pi];
        const point& pNext = ps[ps.fcIndex(pi)];

        const vector a = (pNext - p)^(pAvg - p);
        const vector c = p + pNext + pAvg;

        const scalar an = a & sumAHat;

        sumAn += an;
        sumAnc += an*c;
    }




    if (sumAn > vSmall)
    {
        return (1.0/3.0)*sumAnc/sumAn;
    }
    else
    {
        return pAvg;
    }
}


template<class PointField>
Foam::vector Foam::face::area(const PointField& ps)
{

    if (ps.size() == 3)
    {
        return 0.5*((ps[1] - ps[0])^(ps[2] - ps[0]));
    }




    point pAvg = Zero;
    for (Foam::label pi=0; pi<(ps).size(); pi++)
    {
        pAvg += ps[pi];
    }
    pAvg /= ps.size();




    vector sumA = Zero;
    for (Foam::label pi=0; pi<(ps).size(); pi++)
    {
        const point& p = ps[pi];
        const point& pNext = ps[ps.fcIndex(pi)];

        const vector a = (pNext - p)^(pAvg - p);

        sumA += a;
    }

    return 0.5*sumA;
}





template<class Type>
Type Foam::face::average
(
    const pointField& ps,
    const Field<Type>& fld
) const
{

    if (size() == 3)
    {
        return
            (1.0/3.0)
           *(
               fld[operator[](0)]
             + fld[operator[](1)]
             + fld[operator[](2)]
            );
    }





    point pAvg = Zero;
    Type fldAvg = Zero;
    for (Foam::label pi=0; pi<(*this).size(); pi++)
    {
        pAvg += ps[operator[](pi)];
        fldAvg += fld[operator[](pi)];
    }
    pAvg /= size();
    fldAvg /= size();




    vector sumA = Zero;
    for (Foam::label pi=0; pi<(*this).size(); pi++)
    {
        const point& p = ps[operator[](pi)];
        const point& pNext = ps[operator[](fcIndex(pi))];

        const vector a = (pNext - p)^(pAvg - p);

        sumA += a;
    }
    const vector sumAHat = normalised(sumA);



    scalar sumAn = 0;
    Type sumAnf = Zero;
    for (Foam::label pi=0; pi<(*this).size(); pi++)
    {
        const point& p = ps[operator[](pi)];
        const point& pNext = ps[operator[](fcIndex(pi))];

        const vector a = (pNext - p)^(pAvg - p);
        const Type f =
            fld[operator[](pi)]
          + fld[operator[](fcIndex(pi))]
          + fldAvg;

        const scalar an = a & sumAHat;

        sumAn += an;
        sumAnf += an*f;
    }




    if (sumAn > vSmall)
    {
        return (1.0/3.0)*sumAnf/sumAn;
    }
    else
    {
        return fldAvg;
    }
}
