# 35 "/home/g6/a214026/OpenFOAM/env/OpenFOAM-v10/src/OpenFOAM/lnInclude/PrimitivePatchCheck.C"
template<class FaceList, class PointField>
void Foam::PrimitivePatch<FaceList, PointField>::visitPointRegion
(
    const label pointi,
    const labelList& pFaces,
    const label startFacei,
    const label startEdgeI,
    boolList& pFacesHad
) const
{
    label index = findIndex(pFaces, startFacei);

    if (!pFacesHad[index])
    {

        pFacesHad[index] = true;


        const labelList& fEdges = faceEdges()[startFacei];

        label nextEdgeI = -1;

        for (Foam::label i=0; i<(fEdges).size(); i++)
        {
            label edgeI = fEdges[i];

            const edge& e = edges()[edgeI];

            if (edgeI != startEdgeI && (e[0] == pointi || e[1] == pointi))
            {
                nextEdgeI = edgeI;

                break;
            }
        }

        if (nextEdgeI == -1)
        {
            ::Foam::FatalError((__PRETTY_FUNCTION__), "/home/g6/a214026/OpenFOAM/env/OpenFOAM-v10/src/OpenFOAM/lnInclude/PrimitivePatchCheck.C", 73)
                << "Problem: cannot find edge out of " << fEdges
                << "on face " << startFacei << " that uses point " << pointi
                << " and is not edge " << startEdgeI << abort(FatalError);
        }


        const labelList& eFaces = edgeFaces()[nextEdgeI];

        for (Foam::label i=0; i<(eFaces).size(); i++)
        {
            if (eFaces[i] != startFacei)
            {
                visitPointRegion
                (
                    pointi,
                    pFaces,
                    eFaces[i],
                    nextEdgeI,
                    pFacesHad
                );
            }
        }
    }
}




template<class FaceList, class PointField>
typename
Foam::PrimitivePatch<FaceList, PointField>::surfaceTopo
Foam::PrimitivePatch<FaceList, PointField>::
surfaceType() const
{
    if (debug)
    {
        ::Foam::Info((__PRETTY_FUNCTION__), "/home/g6/a214026/OpenFOAM/env/OpenFOAM-v10/src/OpenFOAM/lnInclude/PrimitivePatchCheck.C", 110) << "Calculating patch topology" << endl;
    }

    const labelListList& edgeFcs = edgeFaces();

    surfaceTopo pType = MANIFOLD;

    for (Foam::label edgeI=0; edgeI<(edgeFcs).size(); edgeI++)
    {
        label nNbrs = edgeFcs[edgeI].size();

        if (nNbrs < 1 || nNbrs > 2)
        {
            pType = ILLEGAL;


            return pType;
        }
        else if (nNbrs == 1)
        {

            pType = OPEN;
        }
    }

    if (debug)
    {
        Info<< "    Finished." << endl;
    }

    return pType;
}


template<class FaceList, class PointField>
bool
Foam::PrimitivePatch<FaceList, PointField>::
checkTopology
(
    const bool report,
    labelHashSet* setPtr
) const
{
    if (debug)
    {
        ::Foam::Info((__PRETTY_FUNCTION__), "/home/g6/a214026/OpenFOAM/env/OpenFOAM-v10/src/OpenFOAM/lnInclude/PrimitivePatchCheck.C", 155) << "Checking patch topology" << endl;
    }



    const labelListList& edgeFcs = edgeFaces();

    bool illegalTopo = false;

    for (Foam::label edgeI=0; edgeI<(edgeFcs).size(); edgeI++)
    {
        label nNbrs = edgeFcs[edgeI].size();

        if (nNbrs < 1 || nNbrs > 2)
        {
            illegalTopo = true;

            if (report)
            {
                Info<< "Edge " << edgeI << " with vertices:" << edges()[edgeI]
                    << " has " << nNbrs << " face neighbours"
                    << endl;
            }

            if (setPtr)
            {
                const edge& e = edges()[edgeI];

                setPtr->insert(meshPoints()[e.start()]);
                setPtr->insert(meshPoints()[e.end()]);
            }
        }
    }

    if (debug)
    {
        Info<< "    Finished." << endl;
    }

    return illegalTopo;
}


template<class FaceList, class PointField>
bool
Foam::PrimitivePatch<FaceList, PointField>::
checkPointManifold
(
    const bool report,
    labelHashSet* setPtr
) const
{
    const labelListList& pf = pointFaces();
    const labelListList& pe = pointEdges();
    const labelListList& ef = edgeFaces();
    const labelList& mp = meshPoints();

    bool foundError = false;

    for (Foam::label pointi=0; pointi<(pf).size(); pointi++)
    {
        const labelList& pFaces = pf[pointi];


        boolList pFacesHad(pFaces.size(), false);


        const labelList& pEdges = pe[pointi];
        label startEdgeI = pEdges[0];

        const labelList& eFaces = ef[startEdgeI];

        for (Foam::label i=0; i<(eFaces).size(); i++)
        {


            this->visitPointRegion
            (
                pointi,
                pFaces,
                eFaces[i],
                startEdgeI,
                pFacesHad
            );
        }




        label unset = findIndex(pFacesHad, false);

        if (unset != -1)
        {
            foundError = true;

            label meshPointi = mp[pointi];

            if (setPtr)
            {
                setPtr->insert(meshPointi);
            }

            if (report)
            {
                Info<< "Point " << meshPointi
                    << " uses faces which are not connected through an edge"
                    << nl
                    << "This means that the surface formed by this patched"
                    << " is multiply connected at this point" << nl
                    << "Connected (patch) faces:" << nl;

                for (Foam::label i=0; i<(pFacesHad).size(); i++)
                {
                    if (pFacesHad[i])
                    {
                        Info<< "    " << pFaces[i] << endl;
                    }
                }

                Info<< nl << "Unconnected (patch) faces:" << nl;
                for (Foam::label i=0; i<(pFacesHad).size(); i++)
                {
                    if (!pFacesHad[i])
                    {
                        Info<< "    " << pFaces[i] << endl;
                    }
                }
            }
        }
    }

    return foundError;
}
