template<template<class> class Field, class Type>
Type average(const FieldField<Field, Type>& f)
{
    if (f.size())
    {
        label n = 0;

        for (Foam::label i=0; i<(f).size(); i++)
        {
            n += f[i].size();
        }

        if (n == 0)
        {
            ::Foam::Warning((__PRETTY_FUNCTION__), "/home/g6/a214026/OpenFOAM/env/OpenFOAM-v10/src/OpenFOAM/lnInclude/FieldFieldFunctions.C", 524)
                << "empty fieldField, returning zero" << endl;

            return Zero;
        }

        Type avrg = sum(f)/n;

        return avrg;
    }
    else
    {
        ::Foam::Warning((__PRETTY_FUNCTION__), "/home/g6/a214026/OpenFOAM/env/OpenFOAM-v10/src/OpenFOAM/lnInclude/FieldFieldFunctions.C", 536)
            << "empty fieldField, returning zero" << endl;

        return Zero;
    }
}

