namespace Foam
{





template<class MESH>
class GeoMesh
{

protected:




        const MESH& mesh_;


public:



        typedef MESH Mesh;
        typedef typename MESH::BoundaryMesh BoundaryMesh;





        explicit GeoMesh(const MESH& mesh)
        :
            mesh_(mesh)
        {}





        const objectRegistry& thisDb() const
        {
            return mesh_;
        }





        const MESH& operator()() const
        {
            return mesh_;
        }
};




}
