template<class Type>
void Foam::fvMatrix<Type>::operator*=
(
    const volScalarField::Internal& dsf
)
{
    dimensions_ *= dsf.dimensions();
    lduMatrix::operator*=(dsf.field());
    source_ *= dsf.field();

    for (Foam::label patchi=0; patchi<(boundaryCoeffs_).size(); patchi++)
    {
        scalarField pisf
        (
            dsf.mesh().boundary()[patchi].patchInternalField(dsf.field())
        );

        internalCoeffs_[patchi] *= pisf;
        boundaryCoeffs_[patchi] *= pisf;
    }

    if (faceFluxCorrectionPtr_)
    {
        ::Foam::FatalError((__PRETTY_FUNCTION__), "/home/g6/a214026/OpenFOAM/env/OpenFOAM-v10/src/finiteVolume/lnInclude/fvMatrix.C", 1256)
            << "cannot scale a matrix containing a faceFluxCorrection"
            << abort(FatalError);
    }
}


