Foam::SolverPerformance<Type> Foam::fvMatrix<Type>::fvSolver::solve()
{
    return solve
    (
        fvMat_.psi_.mesh().solution().solverDict
        (
            fvMat_.psi_.select
            (
                !fvMat_.psi_.mesh().schemes().steady()
             && fvMat_.psi_.mesh().data::template lookupOrDefault<bool>
                ("finalIteration", false)
            )
        )
    );
}


