Foam::SolverPerformance<Type> Foam::fvMatrix<Type>::solve(const word& name)
{
    return solve
    (
        psi_.mesh().solution().solverDict
        (
            !psi_.mesh().schemes().steady()
         && psi_.mesh().data::template lookupOrDefault<bool>
            ("finalIteration", false)
          ? word(name + "Final")
          : name
        )
    );
}


