inline Foam::point Foam::treeBoundBox::corner(const direction octant) const
{
    return point
    (
        (octant & octantBit::rightHalf) ? max().x() : min().x(),
        (octant & octantBit::topHalf) ? max().y() : min().y(),
        (octant & octantBit::frontHalf) ? max().z() : min().z()
    );
}



