template<>
class offsetOp<triFace>
{

public:

    inline triFace operator()
    (
        const triFace& x,
        const label offset
    ) const
    {
        triFace result(x);

        for (Foam::label xI=0; xI<(x).size(); xI++)
        {
            result[xI] = x[xI] + offset;
        }
        return result;
    }
};




