# 26 "/home/g6/a214026/OpenFOAM/env/OpenFOAM-v10/src/meshTools/lnInclude/meshToolsTemplates.C"
template<class FaceType>
void Foam::meshTools::writeOBJ
(
    Ostream& os,
    const UList<FaceType>& faces,
    const pointField& points,
    const labelList& faceLabels
)
{
    Map<label> foamToObj(4*faceLabels.size());

    label vertI = 0;

    for (Foam::label i=0; i<(faceLabels).size(); i++)
    {
        const FaceType& f = faces[faceLabels[i]];

        for (Foam::label fp=0; fp<(f).size(); fp++)
        {
            if (foamToObj.insert(f[fp], vertI))
            {
                writeOBJ(os, points[f[fp]]);
                vertI++;
            }
        }

        os << 'l';
        for (Foam::label fp=0; fp<(f).size(); fp++)
        {
            os << ' ' << foamToObj[f[fp]]+1;
        }
        os << ' ' << foamToObj[f[0]]+1 << endl;
    }
}


template<class FaceType>
void Foam::meshTools::writeOBJ
(
    Ostream& os,
    const UList<FaceType>& faces,
    const pointField& points
)
{
    labelList allFaces(faces.size());
    for (Foam::label i=0; i<(allFaces).size(); i++)
    {
        allFaces[i] = i;
    }
    writeOBJ(os, faces, points, allFaces);
}
