namespace vismodule
{
class Camera;
class TransferFunction;
}

namespace jpv
{

class Serializer
{
public:
    template<typename T>
    static size_t byteSize( const T& object )
    {
        return sizeof( object );
    }
    template<typename T>
    static size_t pack( char* buf, const T& object )
    {
        std::memcpy( buf, object, sizeof( object ) );
        return sizeof( object );
    }
    template<typename T>
    static size_t unpack( const char* buf, T* object )
    {
        std::memcpy( object, buf, sizeof( *object ) );
        return sizeof( *object );
    }
    template<typename T>
    static size_t writeArray( char* buf, const T& t )
    {
        std::memcpy( buf, t, sizeof( t ) );
        return sizeof( t );
    }
    template<typename T>
    static size_t writeArray( char* buf, const T* t, const size_t sz )
    {
        std::memcpy( buf, t, sizeof( T )*sz );
        return sizeof( T ) * sz;
    }
    template<typename T>
    static size_t readArray( const char* buf, T& t )
    {
        std::memcpy( t, buf, sizeof( t ) );
        return sizeof( t );
    }
    template<typename T>
    static size_t readArray( const char* buf, T* t, const size_t sz )
    {
        std::memcpy( t, buf, sizeof( T )*sz );
        return sizeof( T ) * sz;
    }
    template<typename T>
    static size_t write( char* buf, const T& t )
    {
        std::memcpy( buf, &t, sizeof( t ) );
        return sizeof( t );
    }
    template<typename T>
    static size_t read( const char* buf, T* t )
    {
        std::memcpy( t, buf, sizeof( *t ) );
        return sizeof( *t );
    }
};

template<>
size_t Serializer::byteSize<std::string>( const std::string& object );
template<>
size_t Serializer::write<std::string>( char* buf, const std::string& object );
template<>
size_t Serializer::read<std::string>( const char* buf, std::string* object );

template<>
size_t Serializer::byteSize<vismodule::Camera>( const vismodule::Camera& object );
template<>
size_t Serializer::pack<vismodule::Camera>( char* buf, const vismodule::Camera& object );
template<>
size_t Serializer::unpack<vismodule::Camera>( const char* buf, vismodule::Camera* object );

template<>
size_t Serializer::byteSize<vismodule::TransferFunction>( const vismodule::TransferFunction& object );
template<>
size_t Serializer::pack<vismodule::TransferFunction>( char* buf, const vismodule::TransferFunction& object );
template<>
size_t Serializer::unpack<vismodule::TransferFunction>( const char* buf, vismodule::TransferFunction* object );

}
