{
    return( this->rand() * n );
}
# 140 "../../../../VisModule/Numeric/MersenneTwister.h"
inline const double MersenneTwister::rand53( void )
{



    const unsigned long a = this->randInteger() >> 5;
    const unsigned long b = this->randInteger() >> 6;
    return( ( a * 67108864.0 + b ) * ( 1.0 / 9007199254740992.0 ) );
}
# 157 "../../../../VisModule/Numeric/MersenneTwister.h"
inline const unsigned long MersenneTwister::randInteger( void )
{




    if ( m_left == 0 ) { this->reload(); }
    --m_left;

    unsigned long s1;
    s1 = *m_next++;
    s1 ^= ( s1 >> 11 );
    s1 ^= ( s1 << 7 ) & 0x9d2c5680UL;
    s1 ^= ( s1 << 15 ) & 0xefc60000UL;

    return( s1 ^ ( s1 >> 18 ) );
}
# 183 "../../../../VisModule/Numeric/MersenneTwister.h"
inline const unsigned long MersenneTwister::randInteger( const unsigned long n )
{


    unsigned long used = n;
    used |= used >> 1;
    used |= used >> 2;
    used |= used >> 4;
    used |= used >> 8;
    used |= used >> 16;


    unsigned long i;
    do
    {
        i = this->randInteger() & used;
    }
    while ( i > n );

    return( i );
}
# 212 "../../../../VisModule/Numeric/MersenneTwister.h"
inline const double MersenneTwister::operator ()( void )
{
    return( this->rand() );
}
# 224 "../../../../VisModule/Numeric/MersenneTwister.h"
inline void MersenneTwister::reload( void )
{


    unsigned long* p = m_state;
    int i;

    for ( i = N - M; i--; ++p )
    {
        *p = twist( p[M], p[0], p[1] );
    }

    for ( i = M; --i; ++p )
    {
        *p = twist( p[M - N], p[0], p[1] );
    }
    *p = twist( p[M - N], p[0], m_state[0] );

    m_left = N, m_next = m_state;
}
