template <typename T>
const vismodule::Vector3f QuadraticTetrahedralCell<T>::randomSampling() const
{




    float s;
    float t;
    float u;
            
# 580 "../../../../VisModule/Visualization/Mapper/QuadraticTetrahedralCell.h"
#pragma omp critical(random)
# 580 "../../../../VisModule/Visualization/Mapper/QuadraticTetrahedralCell.h"

    {
        s = BaseClass::randomNumber();
        t = BaseClass::randomNumber();
        u = BaseClass::randomNumber();
    }

    vismodule::Vector3f point;
    if ( s + t + u <= 1.0f )
    {
        point[0] = s;
        point[1] = t;
        point[2] = u;
    }
    else if ( s - t + u >= 1.0f )
    {

        point[0] = -u + 1.0f;
        point[1] = -s + 1.0f;
        point[2] = t;
    }
    else if ( s + t - u >= 1.0f )
    {

        point[0] = -s + 1.0f;
        point[1] = -t + 1.0f;
        point[2] = u;
    }
    else if ( -s + t + u >= 1.0f )
    {

        point[0] = -u + 1.0f;
        point[1] = s;
        point[2] = -t + 1.0f;
    }
    else
    {

        point[0] = 0.5f * s - 0.5f * t - 0.5f * u + 0.5f;
        point[1] = - 0.5f * s + 0.5f * t - 0.5f * u + 0.5f;
        point[2] = - 0.5f * s - 0.5f * t + 0.5f * u + 0.5f;
    }

    BaseClass::setLocalPoint( point );
    BaseClass::m_global_point = BaseClass::transformLocalToGlobal( point );

    return BaseClass::m_global_point;
}

