enum Token {

    NON,

    VARIABLE,

    VALUE,

    PLUS, MINUS, MULTI, DIVIDE, POW,

    MINUSF,

    SQRT, CBRT, LOG, LOG10, EXP, ABS, FLOOR, CEIL,
    SIN, COS, TAN, ASIN, ACOS, ATAN, SINH, COSH, TANH, ASINH, ACOSH, ATANH,
    HEAVI,RECTFUNC,

    SIGMOID, GAUSS, MIN, MAX,

    COMMA,

    END,


    LEFT, RIGHT
};

class ExpString
{
public:
    std::string m_str;
    Token m_token;
    VarName m_var;

    ExpString( void ){}

    void set( std::string str, Token token )
        {
            m_str = str;
            m_token = token;
        }

    void set( std::string str, VarName var )
        {
            m_str = str;
            m_var = var;
        }

    bool operator < ( const ExpString& org ) const
        {
            std::string left = org.m_str;
            return m_str.size() < left.size();
        }

    bool operator > ( const ExpString& org ) const
        {
            std::string left = org.m_str;
            return m_str.size() > left.size();
        }
};

class ExpToken
{
public:
    Token m_token;
    VarName m_var;
    double m_value;

    ExpToken( void )
        {
            m_token = NON;
            m_var = NOTHING;
            m_value = 0.0;
        }
};

class Node {
public:
    ExpToken m_exp[256];
    Node* m_left;
    Node* m_right;

    Node( void ){}


    const unsigned int exp_end_pos( void ) const
        {
            unsigned int i = 0;
            while( m_exp[i].m_token != END )
            {
                i++;
            }

            return i;
        }
};
