namespace FuncParser
{

class ReversePolishNotation
{
public:

    int *m_exp_token;
    int *m_variable_name;
    float *m_variable_value;

    float *m_variable_value_array[128];

    float *m_number;


    int m_sp;
    float* m_stack;

    float *m_stack_array;



private:

    int m_array_size;


public:
    ReversePolishNotation( void );

    ReversePolishNotation( int size )
    {
        m_exp_token = new int[size];
        m_variable_name = new int[size];
        m_variable_value = new float[128];
        m_number = new float[size];
        m_stack = new float[size];
    }

    ~ReversePolishNotation( void )
        {




            delete[] m_stack;
        }

public:
    void setExpToken( int* exp_token )
        {
            m_exp_token = exp_token;
        }

    void setVariableName( int* name )
        {
            m_variable_name = name;
        }

    void setNumber( float* num )
        {
            m_number = num;
        }

    void setVariableValue( float* value )
        {
            m_variable_value = value;
        }

    void setVariableValueArray( float* value[128] )
        {
            for(int i=0; i<128; i++){
                m_variable_value_array[i] = value[i];
            }
        }

    void setExpToken( int* exp_token, int size )
        {
            for( int i = 0; i < size; i++ )
            {
                m_exp_token[i] = exp_token[i];
            }
        }

    void setVariableName( int* name, int size )
        {
            for( int i = 0; i < size; i++ )
            {
                m_variable_name[i] = name[i];
            }
        }

    void setNumber( float* num, int size )
        {
            for( int i = 0; i < size; i++ )
            {
                m_number[i] = num[i];
            }
        }

    void setVariableValue( float* value, int size )
        {
            for( int i = 0; i < 128; i++ )
            {
                m_variable_value[i] = value[i];
            }
        }

    void show( void )
    {
        int p=0;
        std::cout<<"exp token: ";
        for(int i=0; i<5; i++)
        {
            std::cout<<m_exp_token[i]<<",";
        }
        std::cout<<std::endl;

        std::cout<<"var name: ";
        for(int i=0; i<5; i++)
        {
            std::cout<<m_variable_name[i]<<",";
        }
        std::cout<<std::endl;

        std::cout<<"val array: ";
        for(int i=0; i<5; i++)
        {
            std::cout<<m_number[i]<<",";
        }
        std::cout<<std::endl;
    }

public:
    float eval( void )
        {


            m_sp = 0;

            int* expr = m_exp_token;
            int* name = m_variable_name;
            float* value = m_variable_value;
            float* number = m_number;

            float tmp1, tmp2, tmp3;

            while( *expr != END )
            {

                switch( *expr )
                {

                case VARIABLE:
                    push( value[*name] );
                    break;


                case VALUE:
                    push( *number );
                    break;


                case PLUS:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = tmp2 + tmp1;
                    push( tmp3 );
                    break;
                case MINUS:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = tmp2 - tmp1;
                    push( tmp3 );
                    break;
                case MULTI:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = tmp2 * tmp1;
                    push( tmp3 );
                    break;
                case DIVIDE:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = tmp2 / tmp1;
                    push( tmp3 );
                    break;
                case POW:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = pow( tmp2, tmp1 );
                    push( tmp3 );
                    break;


                case MINUSF:
                    tmp1 = pop();
                    tmp2 = -tmp1;
                    push( tmp2 );
                    break;


                case SQRT:
                    tmp1 = pop();
                    tmp2 = sqrt( tmp1 );
                    push( tmp2 );
                    break;
                case CBRT:
                    tmp1 = pop();
                    tmp2 = cbrt( tmp1 );
                    push( tmp2 );
                    break;
                case LOG:
                    tmp1 = pop();
                    tmp2 = log( tmp1 );
                    push( tmp2 );
                    break;
                case LOG10:
                    tmp1 = pop();
                    tmp2 = log10( tmp1 );
                    push( tmp2 );
                    break;
                case EXP:
                    tmp1 = pop();
                    tmp2 = exp( tmp1 );
                    push( tmp2 );
                    break;
                case ABS:
                    tmp1 = pop();
                    tmp2 = fabs( tmp1 );
                    push( tmp2 );
                    break;
                case FLOOR:
                    tmp1 = pop();
                    tmp2 = floor( tmp1 );
                    push( tmp2 );
                    break;
                case CEIL:
                    tmp1 = pop();
                    tmp2 = ceil( tmp1 );
                    push( tmp2 );
                    break;
                case SIN:
                    tmp1 = pop();
                    tmp2 = sin( tmp1 );
                    push( tmp2 );
                    break;
                case COS:
                    tmp1 = pop();
                    tmp2 = cos( tmp1 );
                    push( tmp2 );
                    break;
                case TAN:
                    tmp1 = pop();
                    tmp2 = tan( tmp1 );
                    push( tmp2 );
                    break;
                case ASIN:
                    tmp1 = pop();
                    tmp2 = asin( tmp1 );
                    push( tmp2 );
                    break;
                case ACOS:
                    tmp1 = pop();
                    tmp2 = acos( tmp1 );
                    push( tmp2 );
                    break;
                case ATAN:
                    tmp1 = pop();
                    tmp2 = atan( tmp1 );
                    push( tmp2 );
                    break;
                case SINH:
                    tmp1 = pop();
                    tmp2 = sinh( tmp1 );
                    push( tmp2 );
                    break;
                case COSH:
                    tmp1 = pop();
                    tmp2 = cosh( tmp1 );
                    push( tmp2 );
                    break;
                case TANH:
                    tmp1 = pop();
                    tmp2 = tanh( tmp1 );
                    push( tmp2 );
                    break;
                case ASINH:
                    tmp1 = pop();
                    tmp2 = asinh( tmp1 );
                    push( tmp2 );
                    break;
                case ACOSH:
                    tmp1 = pop();
                    tmp2 = acosh( tmp1 );
                    push( tmp2 );
                    break;
                case ATANH:
                    tmp1 = pop();
                    tmp2 = atanh( tmp1 );
                    push( tmp2 );
                    break;
                case HEAVI:
                    tmp1 = pop();
                    tmp2 = tmp1<=0 ? 0 : 1;
                    push( tmp2 );
                    break;
                case RECTFUNC:
                    tmp1 = pop();
                    tmp2 = fabs(tmp1)>0.5 ? 0 : 1;
                    push( tmp2 );
                    break;


                case SIGMOID:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = 1.0/(1.0+exp(tmp1*tmp2));
                    push( tmp3 );
                    break;
                case GAUSS:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = exp(-tmp2*tmp2/(2*tmp1) );
                    push( tmp3 );
                    break;

                case MIN:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = ( ( tmp1 < tmp2 ) ? tmp1 : tmp2 );
                    push( tmp3 );
                    break;

                case MAX:
                    tmp1 = pop();
                    tmp2 = pop();
                    tmp3 = ( ( tmp1 > tmp2 ) ? tmp1 : tmp2 );
                    push( tmp3 );
                    break;


                case COMMA:
                    break;

                default:
                    std::cout<<"unknown token. ->"<<*expr<<std::endl;
                }

                expr++;
                name++;
                number++;
            }

            tmp1 = pop();
            return tmp1;
        }


    void evalArray( float *result, int array_size )
        {




            m_stack_array = new float[128 * array_size];
            m_array_size = array_size;

            m_sp = 0;

            int* expr = m_exp_token;
            int* name = m_variable_name;
            float** value = m_variable_value_array;
            float* number = m_number;


   float *tmp1, *tmp2, *tmp3;
   tmp1 = new float[array_size];
   tmp2 = new float[array_size];
   tmp3 = new float[array_size];

            while( *expr != END )
            {

                switch( *expr )
                {

                case VARIABLE:
                    pushArray( value[*name] );
                    break;


                case VALUE:
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp1[i] = *number;
                    }
                    pushArray( tmp1 );
                    break;


                case PLUS:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = tmp2[i] + tmp1[i];
                    }
                    pushArray( tmp3 );
                    break;
                case MINUS:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = tmp2[i] - tmp1[i];
                    }
                    pushArray( tmp3 );
                    break;
                case MULTI:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = tmp2[i] * tmp1[i];
                    }
                    pushArray( tmp3 );
                    break;
                case DIVIDE:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = tmp2[i] / tmp1[i];
                    }
                    pushArray( tmp3 );
                    break;
                case POW:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = pow( tmp2[i], tmp1[i] );

                    }
                    pushArray( tmp3 );
                    break;


                case MINUSF:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = -tmp1[i];
                    }
                    pushArray( tmp2 );
                    break;


                case SQRT:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = sqrt( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case CBRT:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = cbrt( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case LOG:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = log( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case LOG10:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = log10( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case EXP:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = exp( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case ABS:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = fabs( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case FLOOR:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = floor( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case CEIL:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = ceil( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case SIN:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = sin( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case COS:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = cos( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case TAN:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = tan( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case ASIN:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = asin( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case ACOS:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = acos( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case ATAN:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = atan( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case SINH:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = sinh( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case COSH:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = cosh( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case TANH:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = tanh( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case ASINH:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = asinh( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case ACOSH:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = acosh( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case ATANH:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = atanh( tmp1[i] );
                    }
                    pushArray( tmp2 );
                    break;
                case HEAVI:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = tmp1[i]<=0 ? 0 : 1;
                    }
                    pushArray( tmp2 );
                    break;
                case RECTFUNC:
                    popArray( tmp1 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp2[i] = fabs(tmp1[i])>0.5 ? 0 : 1;
                    }
                    pushArray( tmp2 );
                    break;


                case SIGMOID:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = 1.0/(1.0+exp(tmp1[i]*tmp2[i]));
                    }
                    pushArray( tmp3 );
                    break;
                case GAUSS:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = exp(-tmp2[i]*tmp2[i]/(2*tmp1[i]) );
                    }
                    pushArray( tmp3 );
                    break;

                case MIN:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = ( ( tmp1[i] < tmp2[i] ) ? tmp1[i] : tmp2[i] );
                    }
                    pushArray( tmp3 );
                    break;

                case MAX:
                    popArray( tmp1 );
                    popArray( tmp2 );
                    for ( int i=0; i<array_size; i++ )
                    {
                        tmp3[i] = ( ( tmp1[i] > tmp2[i] ) ? tmp1[i] : tmp2[i] );
                    }
                    pushArray( tmp3 );
                    break;


                case COMMA:
                    break;

                default:
                    std::cout<<"unknown token. ->"<<*expr<<std::endl;
                }

                expr++;
                name++;
                number++;
            }

            popArray(tmp1);
            for(int i=0; i<array_size; i++){
                result[i] = tmp1[i];
            }

   delete[] tmp1;
   delete[] tmp2;
   delete[] tmp3;
   delete[] m_stack_array;

            return;
        }


protected:

    void push( float f )
        {
            if ( m_sp < 128 )
            {
                m_stack[m_sp++] = f;
            }
            else
            {
                printf("error: stack full, can't push %g\n", f);
            }
        }


    float pop( void )
        {
            if ( m_sp > 0 )
            {
                return m_stack[--m_sp];
            }
            else
            {
  printf("error: stack empty\n");
  return 0.0;
            }
        }



    void pushArray( float *f )
    {
        if ( m_sp < 128 )
        {
            for ( int i=0; i<m_array_size; i++ )
            {
                m_stack_array[m_sp*m_array_size+i] = f[i];
            }
            m_sp++;
        }
        else
            {
                printf("error: stack full, can't push %g\n", f);
            }
    }


    void popArray( float *f )
    {
        if ( m_sp > 0 )
        {
            --m_sp;
            for ( int i=0; i<m_array_size; i++ )
            {
                f[i] = m_stack_array[m_sp*m_array_size+i];
            }
        }
        else
        {
            printf("error: stack empty\n");
        }
    }

};

}
