template <class T>
inline const T CommandLine::value( size_t index ) const
{
    return( m_values[index].value<T>() );
}
# 321 "../../../../VisModule/Utility/CommandLine.h"
template <class T>
inline const T CommandLine::optionValue( const std::string& option_name, size_t index ) const
{
    Option key( option_name );
    Options::const_iterator option =
        std::find( m_options.begin(), m_options.end(), key );

    if ( ( option == m_options.end() ) || ( !option->isGiven() ) )
    {
        ( vismodule::Message( vismodule::Message::Error, "../../../../VisModule/Utility/CommandLine.h", 330, __PRETTY_FUNCTION__ ) )( "Cannot find '-%s' option.", option->name().c_str() );
        return( T( 0 ) );
    }

    if ( (size_t)( option->nvalues() ) < index )
    {
        ( vismodule::Message( vismodule::Message::Error, "../../../../VisModule/Utility/CommandLine.h", 336, __PRETTY_FUNCTION__ ) )( "Cannot get option value by given index." );
        return( T( 0 ) );
    }

    T ret = option->value<T>( index );
    return( ret );
}
# 351 "../../../../VisModule/Utility/CommandLine.h"
template <typename T>
inline const T CommandLine::Option::value( size_t index ) const
{
    if ( m_nvalues < index )
    {
        ( vismodule::Message( vismodule::Message::Error, "../../../../VisModule/Utility/CommandLine.h", 356, __PRETTY_FUNCTION__ ) )( "Option '-%s' has only %d values.",
                         m_name.c_str(), m_nvalues );
        return( T( 0 ) );
    }

    T ret;
    std::stringstream s( m_values[index].data() );
    s >> ret;

    return( ret );
}
# 375 "../../../../VisModule/Utility/CommandLine.h"
template<>
inline const std::string CommandLine::Option::value<std::string>( size_t index ) const
{
    if ( m_nvalues < index )
    {
        ( vismodule::Message( vismodule::Message::Error, "../../../../VisModule/Utility/CommandLine.h", 380, __PRETTY_FUNCTION__ ) )( "Option '-%s' has only %d values.",
                         m_name.c_str(), m_nvalues );
        return( "" );
    }

    return( m_values[index].data() );
}







template <typename T>
inline const T CommandLine::Value::value( void ) const
{
    T ret;
    std::stringstream s( m_value.data() );
    s >> ret;

    return( ret );
}







template <>
inline const std::string CommandLine::Value::value<std::string>( void ) const
{
    return( m_value.data() );
}

