inline vtkDataArray* vtkDataArray::FastDownCast(vtkAbstractArray* source)
{
  if (source)
  {
    switch (source->GetArrayType())
    {
      case AoSDataArrayTemplate:
      case SoADataArrayTemplate:
      case TypedDataArray:
      case DataArray:
      case MappedDataArray:
        return static_cast<vtkDataArray*>(source);
      default:
        break;
    }
  }
  return nullptr;
}

template <> struct vtkArrayDownCast_impl<vtkDataArray> { inline vtkDataArray* operator()(vtkAbstractArray* array) { return vtkDataArray::FastDownCast(array); } };



